#define main block_auth_embedded_main
#include "block_auth.cpp"
#undef main

#include <sstream>

struct PGroup{std::vector<int>ids;std::vector<float>lo,hi;};
struct PCluster{std::vector<int>pivots;std::vector<int>ids;std::vector<float>sig;};
struct PCfg{std::string data="../dataset/sift",assign="../populated_index/PriorMax_SIFT1M_C100_clusterid.tsv",out="pivot_batch_results.csv";int base=100000,nq=50,k=100,max_pivots=8;std::vector<int>probes{8,16,32,64,100},pcounts{1,2,4,8},blocks{4,8,16,32};};
static std::vector<int>pints(const std::string&s){std::vector<int>v;std::stringstream ss(s);std::string z;while(std::getline(ss,z,','))v.push_back(std::stoi(z));return v;}
static PCfg pparse(int ac,char**av){PCfg c;for(int i=1;i<ac;++i){std::string a=av[i];auto v=[&](){if(++i==ac)throw std::runtime_error("missing value");return std::string(av[i]);};if(a=="--dataset")c.data=v();else if(a=="--assignments")c.assign=v();else if(a=="--output")c.out=v();else if(a=="--base")c.base=std::stoi(v());else if(a=="--queries")c.nq=std::stoi(v());else if(a=="--k")c.k=std::stoi(v());else if(a=="--nprobes")c.probes=pints(v());else if(a=="--pivot-counts")c.pcounts=pints(v());else if(a=="--block-sizes")c.blocks=pints(v());else throw std::runtime_error("unknown option "+a);}for(int p:c.pcounts)c.max_pivots=std::max(c.max_pivots,p);return c;}
static std::vector<std::vector<int>>plists(const std::string&p,size_t n){std::ifstream f(p);if(!f)throw std::runtime_error("cannot open assignments");std::vector<std::vector<int>>ls(100);long id,c;size_t z=0;while(f>>id>>c)if(id>=0&&(size_t)id<n){ls[c].push_back(id);++z;}if(z!=n)throw std::runtime_error("assignment prefix mismatch");return ls;}

static PCluster make_pcluster(const Matrix&xb,const std::vector<int>&ids,const std::vector<float>&center,int P){PCluster c;c.ids=ids;if(ids.empty())return c;int first=ids[0];float best=-1;for(int id:ids){float d=l2(xb[id],center.data(),xb.d);if(d>best){best=d;first=id;}}c.pivots.push_back(first);std::vector<float>mind(ids.size(),std::numeric_limits<float>::infinity());for(int z=1;z<P;++z){int next=ids[0];float far=-1;int last=c.pivots.back();for(size_t i=0;i<ids.size();++i){mind[i]=std::min(mind[i],l2(xb[ids[i]],xb[last],xb.d));if(mind[i]>far){far=mind[i];next=ids[i];}}c.pivots.push_back(next);}c.sig.resize(ids.size()*P);for(size_t i=0;i<ids.size();++i)for(int p=0;p<P;++p)c.sig[i*P+p]=std::sqrt(l2(xb[ids[i]],xb[c.pivots[p]],xb.d));return c;}

static void group_rec(const PCluster&c,int P,int block,std::vector<int>&pos,int begin,int end,std::vector<PGroup>&out){int n=end-begin;if(n<=block){PGroup g;g.lo.assign(P,std::numeric_limits<float>::infinity());g.hi.assign(P,-std::numeric_limits<float>::infinity());g.ids.reserve(n);for(int z=begin;z<end;++z){int i=pos[z];g.ids.push_back(c.ids[i]);for(int p=0;p<P;++p){float v=c.sig[(size_t)i*c.pivots.size()+p];g.lo[p]=std::min(g.lo[p],v);g.hi[p]=std::max(g.hi[p],v);}}for(int p=0;p<P;++p){g.lo[p]=std::nextafter(g.lo[p],-std::numeric_limits<float>::infinity());g.hi[p]=std::nextafter(g.hi[p],std::numeric_limits<float>::infinity());}out.push_back(std::move(g));return;}int sd=0;float range=-1;for(int p=0;p<P;++p){float lo=std::numeric_limits<float>::infinity(),hi=-lo;for(int z=begin;z<end;++z){float v=c.sig[(size_t)pos[z]*c.pivots.size()+p];lo=std::min(lo,v);hi=std::max(hi,v);}if(hi-lo>range){range=hi-lo;sd=p;}}int mid=begin+n/2;std::nth_element(pos.begin()+begin,pos.begin()+mid,pos.begin()+end,[&](int a,int b){float x=c.sig[(size_t)a*c.pivots.size()+sd],y=c.sig[(size_t)b*c.pivots.size()+sd];return x<y||(x==y&&a<b);});group_rec(c,P,block,pos,begin,mid,out);group_rec(c,P,block,pos,mid,end,out);}
static std::vector<PGroup>make_groups(const PCluster&c,int P,int block){std::vector<int>pos(c.ids.size());std::iota(pos.begin(),pos.end(),0);std::vector<PGroup>g;if(!pos.empty())group_rec(c,P,block,pos,0,pos.size(),g);return g;}
static float pivot_lb(const PGroup&g,const std::vector<float>&dq){float lb=0;for(size_t p=0;p<dq.size();++p){float z=0;if(dq[p]<g.lo[p])z=g.lo[p]-dq[p];else if(dq[p]>g.hi[p])z=dq[p]-g.hi[p];lb=std::max(lb,z);}return lb;}

int main(int ac,char**av)try{PCfg cfg=pparse(ac,av);Matrix xb=fvecs(cfg.data+"/sift_base.fvecs",cfg.base),xq=fvecs(cfg.data+"/sift_query.fvecs",cfg.nq);auto ls=plists(cfg.assign,xb.rows());auto cs=centers(xb,ls);SQ4 sq(xb);std::cerr<<"Selecting farthest-first pivots and computing signatures...\n";std::vector<PCluster>pc(100);for(int c=0;c<100;++c)pc[c]=make_pcluster(xb,ls[c],cs[c],cfg.max_pivots);
struct Q{std::vector<int>clusters;float tau;uint64_t visited=0,flat_exact=0;};std::vector<std::vector<Q>>qs(cfg.probes.size(),std::vector<Q>(xq.rows()));for(size_t pi=0;pi<cfg.probes.size();++pi)for(size_t qi=0;qi<xq.rows();++qi){int np=cfg.probes[pi];Q&q=qs[pi][qi];std::vector<int>pr(100);std::iota(pr.begin(),pr.end(),0);std::partial_sort(pr.begin(),pr.begin()+np,pr.end(),[&](int a,int b){float x=l2(xq[qi],cs[a].data(),xb.d),y=l2(xq[qi],cs[b].data(),xb.d);return x<y||(x==y&&a<b);});q.clusters.assign(pr.begin(),pr.begin()+np);std::priority_queue<std::pair<float,int>>top;for(int c:q.clusters)for(int id:ls[c]){float d=l2(xq[qi],xb[id],xb.d);++q.visited;if((int)top.size()<cfg.k)top.push({d,id});else if(d<top.top().first){top.pop();top.push({d,id});}}q.tau=std::sqrt(top.top().first);for(int c:q.clusters)for(int id:ls[c])q.flat_exact+=sq.lb(xq[qi],id)<=q.tau;}
std::ofstream out(cfg.out);out<<"base,k,nprobe,pivots,block_size,avg_groups,avg_group_size,prune_ratio,avg_opened,avg_exact,summary_bytes,flat_bytes,pivot_bytes,vo_reduction\n";std::cout<<"nprobe pivots block prune reduction\n";
for(int P:cfg.pcounts)for(int block:cfg.blocks){std::vector<std::vector<PGroup>>groups(100);for(int c=0;c<100;++c)groups[c]=make_groups(pc[c],P,block);for(size_t pi=0;pi<cfg.probes.size();++pi){uint64_t vis=0,fexact=0,ng=0,pruned=0,opened=0,exact=0;double summaries=0;for(size_t qi=0;qi<xq.rows();++qi){const Q&q=qs[pi][qi];vis+=q.visited;fexact+=q.flat_exact;for(int c:q.clusters){std::vector<float>dq(P);for(int p=0;p<P;++p)dq[p]=std::sqrt(l2(xq[qi],xb[pc[c].pivots[p]],xb.d));for(const PGroup&g:groups[c]){++ng;summaries+=40+8*P;if(pivot_lb(g,dq)>q.tau)pruned+=g.ids.size();else{opened+=g.ids.size();for(int id:g.ids)if(sq.lb(xq[qi],id)<=q.tau)++exact;}}}}double nq=xq.rows(),flat=vis*72.0/nq+fexact*512.0/nq,bytes=summaries/nq+opened*72.0/nq+exact*512.0/nq;out<<xb.rows()<<','<<cfg.k<<','<<cfg.probes[pi]<<','<<P<<','<<block<<','<<ng/nq<<','<<vis/(double)ng<<','<<pruned/(double)vis<<','<<opened/nq<<','<<exact/nq<<','<<summaries/nq<<','<<flat<<','<<bytes<<','<<1-bytes/flat<<'\n';std::cout<<std::setw(6)<<cfg.probes[pi]<<' '<<std::setw(3)<<P<<' '<<std::setw(4)<<block<<' '<<std::fixed<<std::setprecision(4)<<pruned/(double)vis<<' '<<1-bytes/flat<<'\n';}}
std::cerr<<"Wrote "<<cfg.out<<"\n";return 0;}catch(const std::exception&e){std::cerr<<"error: "<<e.what()<<'\n';return 1;}
